from pathlib import Path
import json
r=Path(__file__).resolve().parents[2]
m=json.loads((r/'art/compiled/manifest.json').read_text())
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Greyhaven · Art and sound</title><style>body{background:#13262b;color:#e8ddbf;font:17px system-ui;margin:0}main{max-width:1120px;margin:auto;padding:48px 24px}h1{font:48px Georgia;margin:10px 0}h2{font:30px Georgia;color:#d7b671}p{line-height:1.6;max-width:800px}section{background:#1c3439;padding:24px;margin:24px 0;border:1px solid #53605a;border-radius:12px}canvas{width:100%;height:auto;background:#112126;border-radius:8px}select,button{font:inherit;background:#e1c68d;color:#13262b;padding:8px;border:0;border-radius:4px;margin:4px}audio{width:min(100%,600px);display:block;margin:12px 0}.sources{display:grid;grid-template-columns:1fr 1fr;gap:16px}.sources img{width:100%;background:#30464a}small{color:#a5b7b4}@media(max-width:650px){.sources{grid-template-columns:1fr}}</style><main><small>GREYHAVEN · PHASE 8</small><h1>The island, brought to life.</h1><p>Original painted cutouts, shared animation rigs and an original synthesized soundtrack. This offline sampler uses the same compiled assets as the game. Extract the complete release before opening it.</p><section><h2>The cast</h2><select id="clip"><option>walk</option><option>idle</option><option>attack</option><option>cast</option></select><select id="face"></select><canvas id="cast" width="1050" height="220"></canvas><small>Eight facings · tile-authoritative movement in the game · shared cutout animation</small></section><section><h2>Sound of Greyhaven</h2><p>Three regional scores, four ambient loops and 32 effects. Select a cue and press play.</p><select id="cue"></select><audio id="sound" controls></audio><small>Original PCM synthesis. No recordings or external soundfonts.</small></section><section><h2>Production source sheets</h2><div class="sources">'''
for n in ['architecture','creatures','relics','panels']:page+=f'<figure><img src="art/source/phase8/{n}.png" alt="Original {n} source atlas"><figcaption>{n.title()}</figcaption></figure>'
page+='''</div></section><p>Launch <b>Run-Greyhaven.cmd</b> on Windows x64. In the game, <b>F8</b> opens Master, Effects, Music and Ambience controls. See <a style="color:#e1c68d" href="docs/PHASE_8.md">the production notes</a> for pipeline and compatibility details.</p></main><script>const manifest=MANIFEST;const names=['humanoid-h1-s1-b1','resident-linen','tidehound','shore-raider','reef-slinger','salt-hexer','brineguard'];const images=names.map(n=>{let i=new Image;i.src='art/compiled/'+manifest.actors[n].image;return i});const faces=Object.keys(manifest.actors[names[0]].directions);faces.forEach(f=>face.add(new Option(f,f)));face.value=faces[3];let ctx=cast.getContext('2d');function render(t){ctx.clearRect(0,0,1050,220);names.forEach((name,j)=>{let d=manifest.actors[name].directions[face.value][clip.value];let f=d.start+Math.floor(t/120)%d.count;ctx.drawImage(images[j],f%16*128,Math.floor(f/16)*128,128,128,j*150+10,10,128,128);ctx.fillStyle='#e1c68d';ctx.font='13px system-ui';ctx.fillText(name.replace('humanoid-h1-s1-b1','Adventurer'),j*150+8,177)});requestAnimationFrame(render)};Promise.all(images.map(i=>i.decode())).then(()=>requestAnimationFrame(render));const cues=CUES;cues.forEach(n=>cue.add(new Option(n,n)));function playCue(){sound.src='content/original/audio/'+cue.value+'.wav';sound.loop=cue.value.startsWith('music-')||cue.value.startsWith('ambient-')}cue.onchange=playCue;playCue();</script>'''
a=json.loads((r/'art/source/phase8/audio-production.json').read_text())
page=page.replace('MANIFEST',json.dumps(m)).replace('CUES',json.dumps([x['name'] for x in a['cues']]))
(r/'Start-Media-Preview.html').write_text(page)
